-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 16 recettes, 3 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';
    if jsonb_typeof(ph) is distinct from 'object'
       or nullif(ph->>'url', '') is null or nullif(ph->>'page', '') is null
       or nullif(ph->>'license', '') is null then
      raise exception 'Photo vérifiée obligatoire pour %', r->>'slug';
    end if;
    -- Un nouveau slug ne doit pas recréer un plat déjà importé sous un autre nom.
    if exists (
      select 1 from public.recipes existing
      where existing.id <> rid and existing.country_code = r->>'country'
        and lower(regexp_replace(regexp_replace(coalesce(existing.original_title, existing.title), '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
          = lower(regexp_replace(regexp_replace(r->>'original', '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
    ) then
      raise exception 'Doublon de plat détecté pour %', r->>'slug';
    end if;

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, coalesce(r->>'reference', ph->>'page'),
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', coalesce(ph->>'source', 'Wikimedia Commons'), ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · ' || coalesce(ph->>'source', 'Wikimedia Commons'),
        true, true, 'Photo libre vérifiée à l’œil : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"crepes-suzette","country":"FR","place":"fr-paris","original":"Crêpes Suzette","title":"Crêpes Suzette (beurre à l’orange flambé au Grand Marnier)","en":"Crêpes Suzette","es":"Crepes Suzette","desc":"Dessert de la grande restauration parisienne de la Belle Époque : fines crêpes pliées en quatre, chauffées dans un beurre caramélisé au sucre, au jus et au zeste d’orange, puis flambées à la liqueur d’orange devant les convives.","cat":"Dessert","diff":"medium","prep":30,"cook":20,"serv":4,"reference":"https://fr.wikipedia.org/wiki/Cr%C3%AApe_Suzette","ing":[["Farine",125,"g","pour les crêpes"],["Œufs",2,null,null],["Lait",300,"ml",null],["Beurre fondu",20,"g","pour la pâte"],["Sucre",30,"g","pour la pâte"],["Beurre",80,"g","pour la sauce"],["Sucre",60,"g","pour la sauce"],["Oranges",2,null,"zeste et jus"],["Liqueur d’orange (Grand Marnier ou Cointreau)",60,"ml",null]],"steps":["Mélanger la farine, le sucre, les œufs, puis le lait et le beurre fondu; laisser reposer 1 heure.","Cuire 8 crêpes très fines dans une poêle beurrée.","Dans une grande poêle, faire fondre le beurre avec le sucre jusqu’à un léger caramel, ajouter le zeste et le jus d’orange et réduire 3 minutes.","Passer chaque crêpe dans la sauce, la plier en quatre et la ranger dans la poêle.","Verser la liqueur chaude, flamber et servir aussitôt en nappant de sauce."],"photo":{"file":"File:Crépe Suzette à la vanille.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/9/90/Cr%C3%A9pe_Suzette_%C3%A0_la_vanille.jpg","page":"https://commons.wikimedia.org/wiki/File:Cr%C3%A9pe_Suzette_%C3%A0_la_vanille.jpg","author":"Arnaud 25","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"tourte-de-blettes-nicoise","country":"FR","place":"fr-nice","original":"Tourte de blettes","title":"Tourte de blettes niçoise (sucrée aux raisins et pignons)","en":"Nice sweet Swiss chard pie (with raisins and pine nuts)","es":"Tarta de acelgas nizarda (dulce, con pasas y piñones)","desc":"Dessert typique de Nice : feuilles de blettes hachées mêlées à des raisins secs macérés dans le rhum, des pignons, des pommes, du parmesan et du sucre, entre deux pâtes sablées, et saupoudrées de sucre glace.","cat":"Dessert","diff":"medium","prep":40,"cook":40,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Tourte_de_blettes","ing":[["Farine",400,"g","pour la pâte"],["Sucre",100,"g","pour la pâte"],["Beurre",150,"g","pour la pâte"],["Œufs",3,null,"1 pour la pâte, 2 pour la farce"],["Feuilles de blettes",800,"g","sans les côtes"],["Raisins secs",80,"g","macérés dans le rhum"],["Rhum",3,"c. à soupe",null],["Pignons de pin",50,"g",null],["Pommes",2,null,"en fines lamelles"],["Cassonade",100,"g",null],["Parmesan râpé",40,"g",null],["Sucre glace",2,"c. à soupe",null]],"steps":["Préparer la pâte sablée avec la farine, le sucre, le beurre et 1 œuf; la réfrigérer 30 minutes.","Laver, sécher et hacher finement les feuilles de blettes, puis les presser pour retirer l’eau.","Mélanger les blettes avec les raisins égouttés, les pignons, la cassonade, le parmesan et 2 œufs.","Foncer un moule avec la moitié de la pâte, étaler la farce, couvrir de lamelles de pomme puis du second disque; piquer.","Cuire 40 minutes à 180 °C et saupoudrer de sucre glace; servir tiède ou froid."],"photo":{"file":"File:Tourte de blettes.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/a/ad/Tourte_de_blettes.jpg","page":"https://commons.wikimedia.org/wiki/File:Tourte_de_blettes.jpg","author":"Assassas77","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"croustade-gasconne","country":"FR","place":"fr-gascogne","original":"Croustade gasconne","title":"Croustade gasconne aux pommes et à l’armagnac (pastis gascon)","en":"Gascon croustade (apple and armagnac pastry)","es":"Croustade gascona (hojaldre de manzana y armañac)","desc":"Pâtisserie de Gascogne, aussi appelée pastis gascon : feuilles de pâte étirée aussi fine que du papier, beurrées et sucrées, superposées sur des pommes macérées à l’armagnac, le dessus froissé en voiles croustillants.","cat":"Dessert","diff":"hard","prep":45,"cook":40,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Pastis_gascon","ing":[["Pâte filo",10,"feuilles","à défaut de pâte étirée maison"],["Pommes",5,null,"en fines lamelles"],["Armagnac",60,"ml",null],["Sucre",100,"g",null],["Beurre fondu",120,"g",null],["Eau de fleur d’oranger",1,"c. à soupe",null],["Pruneaux d’Agen",8,null,"facultatif"],["Sucre glace",2,"c. à soupe",null]],"steps":["Faire macérer les pommes 2 heures avec l’armagnac, la fleur d’oranger et la moitié du sucre.","Beurrer un moule et y superposer 5 feuilles en les badigeonnant chacune de beurre et en les saupoudrant de sucre, en laissant déborder.","Garnir des pommes égouttées et des pruneaux, puis rabattre les bords.","Froisser les feuilles restantes beurrées et sucrées en voiles et les poser sur le dessus.","Cuire 35 à 40 minutes à 180 °C, arroser du jus de macération et saupoudrer de sucre glace."],"photo":{"file":"File:Croustade gasconne aux pruneaux.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/d/d2/Croustade_gasconne_aux_pruneaux.jpg","page":"https://commons.wikimedia.org/wiki/File:Croustade_gasconne_aux_pruneaux.jpg","author":"Pierre LANNES","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0"}},{"slug":"tarte-au-citron-meringuee","country":"FR","original":"Tarte au citron meringuée","title":"Tarte au citron meringuée (crème au citron et meringue dorée)","en":"French lemon meringue tart","es":"Tarta de limón merengada","desc":"Classique de la pâtisserie française : pâte sucrée cuite à blanc, garnie d’une crème au citron acidulée liée aux œufs et au beurre, couverte d’une meringue dorée au chalumeau ou au four.","cat":"Dessert","diff":"medium","prep":45,"cook":30,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Tarte_au_citron","ing":[["Pâte sucrée",1,null,"pour un moule de 24 cm"],["Citrons non traités",4,null,"zeste et jus"],["Sucre",150,"g","pour la crème"],["Œufs",3,null,null],["Fécule de maïs",20,"g",null],["Beurre",80,"g",null],["Blancs d’œufs",3,null,"pour la meringue"],["Sucre",150,"g","pour la meringue"]],"steps":["Cuire la pâte à blanc 20 minutes à 180 °C.","Fouetter les œufs, le sucre, la fécule, le zeste et le jus de citron, puis cuire à feu doux en remuant jusqu’à épaississement.","Hors du feu, incorporer le beurre en morceaux, verser sur le fond de tarte et laisser prendre.","Monter les blancs en neige en ajoutant le sucre peu à peu jusqu’à obtenir une meringue ferme et brillante.","Pocher ou étaler la meringue sur la crème et la colorer au chalumeau ou 5 minutes sous le gril."],"photo":{"file":"File:Tarte au citron meringuée 2.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/b/b2/Tarte_au_citron_meringu%C3%A9e_2.jpg","page":"https://commons.wikimedia.org/wiki/File:Tarte_au_citron_meringu%C3%A9e_2.jpg","author":"Arnaud 25","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"saint-honore","country":"FR","place":"fr-paris","original":"Saint-honoré","title":"Saint-honoré (choux caramélisés et crème chiboust)","en":"Saint-Honoré cake","es":"Pastel Saint-Honoré","desc":"Gâteau créé à Paris vers 1847 chez le pâtissier Chiboust, rue Saint-Honoré, et nommé d’après le patron des boulangers : fond de pâte feuilletée, couronne de petits choux trempés dans le caramel, garniture de crème chiboust ou de chantilly pochée à la douille.","cat":"Dessert","diff":"hard","prep":90,"cook":45,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Saint-honor%C3%A9_(g%C3%A2teau)","ing":[["Pâte feuilletée",250,"g",null],["Eau",125,"ml","pour la pâte à choux"],["Beurre",50,"g","pour la pâte à choux"],["Farine",75,"g","pour la pâte à choux"],["Œufs",2,null,"pour la pâte à choux"],["Lait",250,"ml","pour la crème"],["Jaunes d’œufs",3,null,null],["Sucre",80,"g","pour la crème"],["Fécule de maïs",25,"g",null],["Crème liquide entière",300,"ml","montée en chantilly"],["Sucre",150,"g","pour le caramel"]],"steps":["Étaler la pâte feuilletée en disque de 22 cm, piquer, pocher un anneau de pâte à choux sur le bord et une vingtaine de petits choux à part; cuire 25 minutes à 190 °C.","Préparer une crème pâtissière avec le lait, les jaunes, le sucre et la fécule; la refroidir puis l’alléger d’un tiers de la chantilly.","Garnir les petits choux de crème par le dessous.","Cuire le sucre en caramel blond, y tremper le dessus de chaque chou et les coller sur l’anneau.","Remplir le centre de crème et décorer de chantilly à la douille à saint-honoré; réfrigérer avant de servir."],"photo":{"file":"File:Gâteau saint-honoré pâtissier (avr 2023).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/8/89/G%C3%A2teau_saint-honor%C3%A9_p%C3%A2tissier_%28avr_2023%29.jpg","page":"https://commons.wikimedia.org/wiki/File:G%C3%A2teau_saint-honor%C3%A9_p%C3%A2tissier_(avr_2023).jpg","author":"Sebleouf","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"gateau-breton","country":"FR","place":"fr-bretagne","original":"Gâteau breton","title":"Gâteau breton au beurre demi-sel","en":"Gâteau breton (Breton butter cake)","es":"Gâteau breton (pastel bretón de mantequilla)","desc":"Gâteau de Bretagne dense et sablé, très riche en beurre demi-sel et en jaunes d’œufs, doré et rayé en croisillons à la fourchette; nature ou fourré de pruneaux ou de confiture.","cat":"Dessert","diff":"easy","prep":20,"cook":45,"serv":8,"reference":"https://fr.wikipedia.org/wiki/G%C3%A2teau_breton","ing":[["Farine",300,"g",null],["Beurre demi-sel mou",250,"g",null],["Sucre",200,"g",null],["Jaunes d’œufs",6,null,"dont 1 pour la dorure"],["Rhum",2,"c. à soupe","facultatif"],["Vanille",1,"c. à thé",null]],"steps":["Battre le beurre mou avec le sucre jusqu’à obtenir une crème.","Ajouter 5 jaunes un à un, le rhum et la vanille, puis la farine en mélangeant sans travailler.","Étaler la pâte dans un moule beurré de 24 cm sur 2 cm d’épaisseur.","Dorer au jaune d’œuf dilué et rayer le dessus en croisillons à la fourchette.","Cuire 45 minutes à 170 °C jusqu’à ce que le gâteau soit bien doré; laisser refroidir avant de démouler."],"photo":{"file":"File:Gâteau breton.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/6/6e/G%C3%A2teau_breton.jpg","page":"https://commons.wikimedia.org/wiki/File:G%C3%A2teau_breton.jpg","author":"Arnaud 25","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"palets-bretons","country":"FR","place":"fr-bretagne","original":"Palets bretons","title":"Palets bretons (sablés épais au beurre salé)","en":"Palets bretons (thick salted-butter shortbread)","es":"Palets bretones (galletas gruesas de mantequilla salada)","desc":"Biscuits épais de Bretagne, cuits dans des cercles pour garder leur forme : pâte sablée très beurrée au beurre demi-sel, friable et dorée.","cat":"Dessert","diff":"easy","prep":20,"cook":20,"serv":20,"reference":"https://fr.wikipedia.org/wiki/Palet_breton","ing":[["Farine",250,"g",null],["Beurre demi-sel mou",200,"g",null],["Sucre",130,"g",null],["Jaunes d’œufs",3,null,null],["Levure chimique",1,"c. à thé",null]],"steps":["Blanchir les jaunes avec le sucre, puis ajouter le beurre mou.","Incorporer la farine et la levure sans trop travailler la pâte.","Former un boudin de 5 cm de diamètre et le réfrigérer 2 heures.","Couper des tranches de 1,5 cm et les placer dans des cercles ou des moules à muffins beurrés.","Cuire 18 à 20 minutes à 180 °C jusqu’à ce qu’ils soient dorés; démouler tiède."],"photo":{"file":"File:Palet breton 02.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/4/4b/Palet_breton_02.jpg","page":"https://commons.wikimedia.org/wiki/File:Palet_breton_02.jpg","author":"Arnaud 25","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"macarons-de-nancy","country":"FR","place":{"slug":"fr-nancy","name":"Nancy","type":"city","lat":48.6921,"lng":6.1844,"summary":"Ancienne capitale des ducs de Lorraine : macarons des Sœurs, bergamotes et baba du roi Stanislas."},"original":"Macarons de Nancy","title":"Macarons de Nancy (macarons craquelés des Sœurs)","en":"Nancy macarons (cracked almond macaroons)","es":"Macarons de Nancy (galletas de almendra agrietadas)","desc":"Biscuits d’amandes de Nancy, popularisés par deux religieuses réfugiées pendant la Révolution, les « Sœurs Macarons » : pâte d’amandes, sucre et blancs d’œufs, cuits sur papier jusqu’à ce que la surface se craquelle.","cat":"Dessert","diff":"medium","prep":20,"cook":15,"serv":20,"reference":"https://fr.wikipedia.org/wiki/Macaron_de_Nancy","ing":[["Amandes en poudre",250,"g",null],["Sucre",300,"g",null],["Blancs d’œufs",3,null,null],["Eau",1,"c. à soupe",null]],"steps":["Mélanger la poudre d’amandes et le sucre, puis ajouter les blancs non montés et l’eau.","Chauffer la pâte quelques minutes au bain-marie en remuant jusqu’à ce qu’elle soit tiède et souple.","Déposer des boules de la taille d’une noix sur une feuille de papier sulfurisé, bien espacées.","Humidifier légèrement le dessus au pinceau pour favoriser le craquelé et laisser croûter 30 minutes.","Cuire 15 minutes à 180 °C; décoller en humidifiant le papier une fois refroidi."],"photo":{"file":"File:Macaron de Nancy - IMG 2841.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/6/68/Macaron_de_Nancy_-_IMG_2841.JPG","page":"https://commons.wikimedia.org/wiki/File:Macaron_de_Nancy_-_IMG_2841.JPG","author":"Shallowell","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"pogne-de-romans","country":"FR","place":{"slug":"fr-romans-sur-isere","name":"Romans-sur-Isère","type":"city","lat":45.0433,"lng":5.0517,"summary":"Ville de la Drôme, berceau de la pogne et des ravioles du Dauphiné."},"original":"Pogne de Romans","title":"Pogne de Romans (brioche en couronne à la fleur d’oranger)","en":"Pogne de Romans (orange blossom brioche ring)","es":"Pogne de Romans (rosca de brioche con azahar)","desc":"Brioche pascale de Romans-sur-Isère et de Valence, en forme de couronne : pâte levée longuement, riche en œufs et en beurre, parfumée à la fleur d’oranger et à la mie dense et filante.","cat":"Pain","diff":"medium","prep":40,"cook":35,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Pogne_de_Romans","ing":[["Farine",500,"g",null],["Levure boulangère fraîche",20,"g",null],["Œufs",5,null,"dont 1 pour la dorure"],["Sucre",120,"g",null],["Beurre mou",150,"g",null],["Eau de fleur d’oranger",3,"c. à soupe",null],["Rhum",1,"c. à soupe","facultatif"],["Sel",1,"c. à thé",null],["Sucre en grains",2,"c. à soupe",null]],"steps":["Préparer un levain avec la levure, 100 g de farine et un peu d’eau tiède; laisser lever 1 heure.","Pétrir le reste de la farine avec les œufs, le sucre, le sel, la fleur d’oranger et le levain, puis incorporer le beurre peu à peu.","Laisser lever 3 heures, ou une nuit au frais.","Former une boule, la percer au centre et l’étirer en couronne; laisser lever 1 h 30.","Dorer, parsemer de sucre en grains et cuire 30 à 35 minutes à 180 °C."],"photo":{"file":"File:Pogne de Romans tranchée.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/b/b8/Pogne_de_Romans_tranch%C3%A9e.jpg","page":"https://commons.wikimedia.org/wiki/File:Pogne_de_Romans_tranch%C3%A9e.jpg","author":"INRA DIST","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0"}},{"slug":"tarte-au-sucre-du-nord","country":"FR","place":"fr-flandre","original":"Tarte au sucre","title":"Tarte au sucre du Nord (pâte briochée à la vergeoise)","en":"Northern French sugar tart (brioche with brown beet sugar)","es":"Tarta de azúcar del Norte (brioche con azúcar moreno de remolacha)","desc":"Dessert du Nord et de Belgique : pâte levée briochée étalée finement, couverte de vergeoise brune, de crème ou d’œuf battu et de noisettes de beurre, qui caramélisent au four.","cat":"Dessert","diff":"easy","prep":25,"cook":25,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Tarte_au_sucre","ing":[["Farine",250,"g",null],["Levure boulangère fraîche",10,"g",null],["Lait tiède",80,"ml",null],["Œuf",1,null,"pour la pâte"],["Beurre mou",60,"g","pour la pâte"],["Sucre",20,"g",null],["Sel",1,"pincée",null],["Vergeoise brune",150,"g",null],["Œuf",1,null,"pour la garniture"],["Crème fraîche",80,"ml",null],["Beurre",40,"g","en noisettes"]],"steps":["Délayer la levure dans le lait tiède, puis pétrir avec la farine, l’œuf, le sucre, le sel et le beurre mou.","Laisser lever 1 h 30.","Étaler la pâte dans un moule à tarte beurré et laisser lever encore 30 minutes.","Couvrir de vergeoise, puis verser l’œuf battu avec la crème et parsemer de noisettes de beurre.","Cuire 20 à 25 minutes à 200 °C; servir tiède."],"photo":{"file":"File:Tarte au sucre.jpeg","url":"https://upload.wikimedia.org/wikipedia/commons/1/11/Tarte_au_sucre.jpeg","page":"https://commons.wikimedia.org/wiki/File:Tarte_au_sucre.jpeg","author":"Popo le Chien","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}},{"slug":"religieuse-patisserie","country":"FR","place":"fr-paris","original":"Religieuse","title":"Religieuse au chocolat (choux superposés et glaçage fondant)","en":"Religieuse (French stacked choux pastry)","es":"Religiosa (pastel de choux superpuestos)","desc":"Pâtisserie parisienne du XIXᵉ siècle : un gros chou surmonté d’un plus petit, garnis de crème pâtissière au chocolat ou au café, glacés au fondant et réunis par une collerette de crème au beurre évoquant l’habit d’une religieuse.","cat":"Dessert","diff":"hard","prep":60,"cook":35,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Religieuse_(p%C3%A2tisserie)","ing":[["Eau",125,"ml","pour la pâte à choux"],["Lait",125,"ml","pour la pâte à choux"],["Beurre",100,"g","pour la pâte à choux"],["Farine",150,"g",null],["Œufs",4,null,"pour la pâte à choux"],["Lait",500,"ml","pour la crème"],["Jaunes d’œufs",4,null,null],["Sucre",100,"g",null],["Fécule de maïs",40,"g",null],["Chocolat noir",100,"g",null],["Fondant pâtissier",250,"g",null],["Cacao en poudre",1,"c. à soupe","pour le fondant"],["Crème au beurre",100,"g","pour la collerette"]],"steps":["Préparer la pâte à choux, pocher 6 gros choux et 6 petits et cuire 25 à 30 minutes à 180 °C.","Préparer une crème pâtissière avec le lait, les jaunes, le sucre et la fécule, puis y faire fondre le chocolat; refroidir.","Garnir les choux de crème par un petit trou percé dessous.","Tiédir le fondant avec le cacao, y tremper le dessus de chaque chou.","Poser les petits choux sur les gros et pocher une collerette de crème au beurre à la jonction."],"photo":{"file":"File:Religieuses au chocolat.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/5/53/Religieuses_au_chocolat.jpg","page":"https://commons.wikimedia.org/wiki/File:Religieuses_au_chocolat.jpg","author":"Sonia Geffrier","license":"Public domain","licenseUrl":null}},{"slug":"tarte-normande","country":"FR","place":"fr-normandie","original":"Tarte normande","title":"Tarte normande aux pommes (appareil à la crème et au calvados)","en":"Normandy apple tart (with cream and calvados custard)","es":"Tarta normanda de manzana (con crema y calvados)","desc":"Tarte de Normandie : pâte brisée garnie de quartiers de pommes, recouverte d’un appareil à la crème fraîche, aux œufs et au calvados, parfois avec de la poudre d’amandes, puis dorée au four.","cat":"Dessert","diff":"easy","prep":25,"cook":40,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Tarte_normande","ing":[["Pâte brisée",1,null,"pour un moule de 26 cm"],["Pommes",5,null,"en lamelles épaisses"],["Œufs",2,null,null],["Crème fraîche épaisse",200,"ml",null],["Sucre",100,"g",null],["Poudre d’amandes",40,"g","facultatif"],["Calvados",3,"c. à soupe",null],["Beurre",20,"g",null]],"steps":["Foncer le moule avec la pâte brisée et la piquer.","Disposer les lamelles de pommes en rosace serrée et les cuire 15 minutes à 200 °C.","Battre les œufs avec la crème, le sucre, la poudre d’amandes et le calvados.","Verser l’appareil sur les pommes et parsemer de noisettes de beurre.","Poursuivre la cuisson 25 minutes à 180 °C jusqu’à ce que la crème soit prise et dorée; servir tiède."],"photo":{"file":"File:Tarte normande.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/6/65/Tarte_normande.jpg","page":"https://commons.wikimedia.org/wiki/File:Tarte_normande.jpg","author":"Ludovic Péron","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}},{"slug":"gateau-de-savoie","country":"FR","place":"fr-savoie","original":"Gâteau de Savoie","title":"Gâteau de Savoie (biscuit très léger aux blancs en neige)","en":"Gâteau de Savoie (Savoy sponge cake)","es":"Bizcocho de Saboya","desc":"Biscuit aérien de Savoie, attribué au cuisinier du comte Amédée VI au XIVᵉ siècle : jaunes et sucre blanchis, farine et fécule, et blancs montés en neige, cuit dans un moule haut à côtes.","cat":"Dessert","diff":"easy","prep":25,"cook":40,"serv":8,"reference":"https://fr.wikipedia.org/wiki/G%C3%A2teau_de_Savoie","ing":[["Œufs",6,null,"séparés"],["Sucre",200,"g",null],["Farine",80,"g",null],["Fécule de pomme de terre",80,"g",null],["Sucre vanillé",1,"sachet",null],["Zeste de citron",1,null,"facultatif"],["Beurre et sucre",1,"c. à soupe","pour le moule"]],"steps":["Beurrer et sucrer un moule à savarin ou à kouglof; préchauffer le four à 160 °C.","Fouetter les jaunes avec le sucre et le sucre vanillé jusqu’à ce que le mélange blanchisse et double.","Incorporer la farine et la fécule tamisées et le zeste.","Monter les blancs en neige ferme et les incorporer délicatement en trois fois.","Verser dans le moule et cuire 40 minutes; démouler tiède et laisser refroidir sur grille."],"photo":{"file":"File:Gateau de savoie.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/a/ae/Gateau_de_savoie.JPG","page":"https://commons.wikimedia.org/wiki/File:Gateau_de_savoie.JPG","author":"Kinni1955","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"oreillettes","country":"FR","place":{"slug":"fr-languedoc","name":"Languedoc","type":"region","lat":43.6,"lng":3.9,"summary":"Pays méditerranéen de Nîmes à Montpellier et aux Cévennes : oreillettes, brandade et tielles."},"original":"Oreillettes","title":"Oreillettes languedociennes (beignets fins à la fleur d’oranger)","en":"Oreillettes (thin orange blossom fritters from Languedoc)","es":"Oreillettes (buñuelos finos de azahar del Languedoc)","desc":"Beignets de carnaval du Languedoc et de Provence : pâte au beurre et aux œufs parfumée à la fleur d’oranger et au zeste, étalée très finement, frite jusqu’à ce qu’elle cloque et saupoudrée de sucre.","cat":"Dessert","diff":"medium","prep":40,"cook":20,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Oreillette_(cuisine)","ing":[["Farine",500,"g",null],["Œufs",3,null,null],["Beurre fondu",100,"g",null],["Sucre",50,"g",null],["Eau de fleur d’oranger",3,"c. à soupe",null],["Zeste d’orange ou de citron",1,null,null],["Sel",1,"pincée",null],["Huile de friture",1,"l",null],["Sucre glace",50,"g",null]],"steps":["Pétrir la farine, les œufs, le beurre fondu, le sucre, la fleur d’oranger, le zeste et le sel en une pâte souple; reposer 2 heures.","Diviser la pâte et l’étaler aussi finement que possible, jusqu’à la rendre presque transparente.","Découper en rectangles à la roulette cannelée et fendre le centre.","Frire quelques secondes de chaque côté dans l’huile à 180 °C jusqu’à ce qu’elles soient blondes et cloquées.","Égoutter sur papier et saupoudrer généreusement de sucre glace."],"photo":{"file":"File:Oreillettes protestantes à Saint-Paul-la-Coste.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/8/84/Oreillettes_protestantes_%C3%A0_Saint-Paul-la-Coste.jpg","page":"https://commons.wikimedia.org/wiki/File:Oreillettes_protestantes_%C3%A0_Saint-Paul-la-Coste.jpg","author":"Mon Œil","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0"}},{"slug":"flan-patissier","country":"FR","place":"fr-paris","original":"Flan pâtissier","title":"Flan pâtissier parisien (crème vanillée sur pâte brisée)","en":"Parisian flan (baked vanilla custard tart)","es":"Flan pastelero parisino (tarta de crema de vainilla)","desc":"Classique des boulangeries parisiennes : pâte brisée garnie d’une épaisse crème pâtissière à la vanille, cuite jusqu’à ce que le dessus soit brun et caramélisé, servie froide en parts.","cat":"Dessert","diff":"easy","prep":25,"cook":50,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Flan_p%C3%A2tissier","ing":[["Pâte brisée",1,null,"pour un moule haut de 22 cm"],["Lait entier",750,"ml",null],["Crème liquide",250,"ml",null],["Œufs",3,null,null],["Jaunes d’œufs",2,null,null],["Sucre",180,"g",null],["Fécule de maïs",90,"g",null],["Gousse de vanille",1,null,"fendue"]],"steps":["Foncer un moule haut ou un cercle avec la pâte et réfrigérer.","Porter le lait et la crème à ébullition avec la vanille grattée.","Fouetter les œufs, les jaunes, le sucre et la fécule, verser le lait chaud dessus, remettre sur le feu et cuire 2 minutes en fouettant jusqu’à épaississement.","Verser la crème chaude dans le fond de tarte et lisser.","Cuire 45 à 50 minutes à 180 °C jusqu’à ce que le dessus soit bien bruni; refroidir complètement avant de démouler."],"photo":{"file":"File:Flan pâtissier ou flan parisien.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/6/68/Flan_p%C3%A2tissier_ou_flan_parisien.jpg","page":"https://commons.wikimedia.org/wiki/File:Flan_p%C3%A2tissier_ou_flan_parisien.jpg","author":"Marianne Casamance","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"navettes-marseillaises","country":"FR","place":"fr-marseille","original":"Navettes de Marseille","title":"Navettes marseillaises (biscuits secs à la fleur d’oranger)","en":"Marseille navettes (orange blossom boat biscuits)","es":"Navettes de Marsella (galletas de azahar en forma de barca)","desc":"Biscuits secs en forme de barque, fabriqués depuis 1781 au Four des Navettes près de l’abbaye Saint-Victor et bénis à la Chandeleur : pâte ferme à la farine, au sucre et à la fleur d’oranger, fendue au centre.","cat":"Dessert","diff":"easy","prep":25,"cook":20,"serv":20,"reference":"https://fr.wikipedia.org/wiki/Navette_(biscuit)","ing":[["Farine",500,"g",null],["Sucre",200,"g",null],["Œufs",2,null,"plus 1 jaune pour la dorure"],["Beurre fondu ou huile d’olive",60,"g",null],["Eau de fleur d’oranger",4,"c. à soupe",null],["Zeste de citron",1,null,"facultatif"],["Sel",1,"pincée",null]],"steps":["Mélanger la farine, le sucre, le sel et le zeste, puis ajouter les œufs, le beurre et la fleur d’oranger pour obtenir une pâte ferme.","Laisser reposer la pâte 1 heure au frais.","Façonner des boudins de 2 cm, couper des tronçons de 8 cm et les pincer aux extrémités en forme de barque.","Les poser sur une plaque, les dorer et inciser profondément le centre sur la longueur.","Cuire 18 à 20 minutes à 180 °C jusqu’à ce qu’elles soient blondes; conserver dans une boîte en fer."],"photo":{"file":"File:Navettes à la fleur d'oranger.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/4/47/Navettes_%C3%A0_la_fleur_d%27oranger.JPG","page":"https://commons.wikimedia.org/wiki/File:Navettes_%C3%A0_la_fleur_d%27oranger.JPG","author":"Véronique PAGNIER","license":"Public domain","licenseUrl":null}}]$batch$::jsonb);
